tool_schemas.implementation:
def decisionFramework(decisionStatement, options, stakeholders, constraints, timeHorizon, riskTolerance, decisionId, analysisType, stage, iteration, nextStageNeeded, criteria=None, criteriaEvaluations=None, possibleOutcomes=None, informationGaps=None, expectedValues=None, multiCriteriaScores=None, sensitivityInsights=None, recommendation=None, suggestedNextStage=None, **_extra):
    import json, os, datetime, time, math, uuid

    _t0 = time.time()
    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0423000" if __import__("os").path.isdir("./environment_mix/0423000") else "/app/database")

    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []

    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)

    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    def _now():
        return datetime.datetime.now(datetime.timezone.utc).isoformat()

    def _is_nonempty_str(x):
        return isinstance(x, str) and x.strip() != ""

    def _is_num(x):
        return isinstance(x, (int, float)) and not isinstance(x, bool)

    def _finite_num(x):
        return _is_num(x) and math.isfinite(float(x))

    def _in01(x):
        return _finite_num(x) and 0.0 <= float(x) <= 1.0

    def _stage_index(s):
        order = ["problem-definition", "options", "criteria", "evaluation", "analysis", "recommendation"]
        try:
            return order.index(s)
        except ValueError:
            return None

    def _gen_id(prefix):
        return f"{prefix}_{uuid.uuid4().hex}"

    def _log(status, error_code=None):
        logs = _load("request_logs.json")
        if not isinstance(logs, list):
            logs = []
        logs.append({
            "id": _gen_id("req"),
            "endpoint": "decisionFramework",
            "credential": None,
            "status": status,
            "error_code": error_code,
            "latency_ms": int((time.time() - _t0) * 1000),
            "timestamp": _now()
        })
        _save("request_logs.json", logs)

    # --- Validate required scalar inputs ---
    if not _is_nonempty_str(decisionId):
        _log("error", "VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "decisionId must be a non-empty string")
    if not _is_nonempty_str(decisionStatement):
        _log("error", "VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "decisionStatement must be a non-empty string")
    if not isinstance(options, list):
        _log("error", "VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "options must be an array")
    if not isinstance(stakeholders, list):
        _log("error", "VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "stakeholders must be an array")
    if not isinstance(constraints, list):
        _log("error", "VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "constraints must be an array")
    if not _is_nonempty_str(timeHorizon):
        _log("error", "VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "timeHorizon must be a non-empty string")
    if riskTolerance not in ["risk-averse", "risk-neutral", "risk-seeking"]:
        _log("error", "VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "Invalid riskTolerance", allowed=["risk-averse", "risk-neutral", "risk-seeking"])
    if analysisType not in ["expected-utility", "multi-criteria", "maximin", "minimax-regret", "satisficing"]:
        _log("error", "VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "Invalid analysisType")
    si = _stage_index(stage)
    if si is None:
        _log("error", "VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "Invalid stage")
    if not _is_num(iteration) or float(iteration) < 0 or not math.isfinite(float(iteration)) or int(float(iteration)) != float(iteration):
        _log("error", "VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "iteration must be a non-negative integer-like number")
    iteration = int(iteration)
    if not isinstance(nextStageNeeded, bool):
        _log("error", "VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "nextStageNeeded must be a boolean")
    if suggestedNextStage is not None and not isinstance(suggestedNextStage, str):
        _log("error", "VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "suggestedNextStage must be a string or null")
    if any((not _is_nonempty_str(s)) for s in stakeholders):
        _log("error", "VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "stakeholders must be a non-empty array of non-empty strings")
    if any((not _is_nonempty_str(s)) for s in constraints):
        _log("error", "VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "constraints must be a non-empty array of non-empty strings")
    if len(stakeholders) == 0:
        _log("error", "VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "stakeholders must be non-empty")
    if len(constraints) == 0:
        _log("error", "VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "constraints must be non-empty")

    # rule: next_stage_needed=false implies stage in ('analysis','recommendation') OR suggested_next_stage is null
    if nextStageNeeded is False:
        if stage not in ["analysis", "recommendation"] and suggestedNextStage is not None and suggestedNextStage.strip() != "":
            _log("error", "VALIDATION_ERROR")
            return _err("VALIDATION_ERROR", "When nextStageNeeded is false, suggestedNextStage must be null unless stage is 'analysis' or 'recommendation'")

    if criteria is None:
        criteria = []
    if criteriaEvaluations is None:
        criteriaEvaluations = []
    if possibleOutcomes is None:
        possibleOutcomes = []
    if informationGaps is None:
        informationGaps = []

    if not isinstance(criteria, list) or not isinstance(criteriaEvaluations, list) or not isinstance(possibleOutcomes, list) or not isinstance(informationGaps, list):
        _log("error", "VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "criteria, criteriaEvaluations, possibleOutcomes, and informationGaps must be arrays when provided")

    if expectedValues is not None and not isinstance(expectedValues, dict):
        _log("error", "VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "expectedValues must be an object when provided")
    if multiCriteriaScores is not None and not isinstance(multiCriteriaScores, dict):
        _log("error", "VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "multiCriteriaScores must be an object when provided")
    if sensitivityInsights is not None and not isinstance(sensitivityInsights, list):
        _log("error", "VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "sensitivityInsights must be an array when provided")
    if sensitivityInsights is not None and any(not isinstance(x, str) for x in sensitivityInsights):
        _log("error", "VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "sensitivityInsights must be an array of strings")

    # validate option payloads
    seen_opt_keys = set()
    for i, o in enumerate(options):
        if not isinstance(o, dict):
            _log("error", "VALIDATION_ERROR")
            return _err("VALIDATION_ERROR", f"options[{i}] must be an object")
        if not _is_nonempty_str(o.get("name")) or not _is_nonempty_str(o.get("description")):
            _log("error", "VALIDATION_ERROR")
            return _err("VALIDATION_ERROR", f"options[{i}].name and options[{i}].description are required and non-empty")
        if "id" in o and o["id"] is not None and not isinstance(o["id"], str):
            _log("error", "VALIDATION_ERROR")
            return _err("VALIDATION_ERROR", f"options[{i}].id must be a string when provided")

        k = o.get("id")
        # If id not provided, stable key will be assigned later; but ensure duplicates among provided ids
        if k is not None:
            if k in seen_opt_keys:
                _log("error", "VALIDATION_ERROR")
                return _err("VALIDATION_ERROR", f"Duplicate option id within request: {k}")
            seen_opt_keys.add(k)

    # validate criteria payloads and weight bounds
    seen_cri_keys = set()
    for i, c in enumerate(criteria):
        if not isinstance(c, dict):
            _log("error", "VALIDATION_ERROR")
            return _err("VALIDATION_ERROR", f"criteria[{i}] must be an object")
        if not _is_nonempty_str(c.get("name")) or not _is_nonempty_str(c.get("description")):
            _log("error", "VALIDATION_ERROR")
            return _err("VALIDATION_ERROR", f"criteria[{i}].name and criteria[{i}].description are required and non-empty")
        if not _in01(c.get("weight")):
            _log("error", "VALIDATION_ERROR")
            return _err("VALIDATION_ERROR", f"criteria[{i}].weight must be within [0,1]")
        if c.get("evaluationMethod") not in ["quantitative", "qualitative", "boolean"]:
            _log("error", "VALIDATION_ERROR")
            return _err("VALIDATION_ERROR", f"criteria[{i}].evaluationMethod is invalid")
        if "id" in c and c["id"] is not None and not isinstance(c["id"], str):
            _log("error", "VALIDATION_ERROR")
            return _err("VALIDATION_ERROR", f"criteria[{i}].id must be a string when provided")
        k = c.get("id")
        if k is not None:
            if k in seen_cri_keys:
                _log("error", "VALIDATION_ERROR")
                return _err("VALIDATION_ERROR", f"Duplicate criterion id within request: {k}")
            seen_cri_keys.add(k)

    # validate evaluations payload
    for i, e in enumerate(criteriaEvaluations):
        if not isinstance(e, dict):
            _log("error", "VALIDATION_ERROR")
            return _err("VALIDATION_ERROR", f"criteriaEvaluations[{i}] must be an object")
        if not _is_nonempty_str(e.get("criterionId")) or not _is_nonempty_str(e.get("optionId")):
            _log("error", "VALIDATION_ERROR")
            return _err("VALIDATION_ERROR", f"criteriaEvaluations[{i}].criterionId and optionId must be non-empty strings")
        if not _in01(e.get("score")):
            _log("error", "VALIDATION_ERROR")
            return _err("VALIDATION_ERROR", f"criteriaEvaluations[{i}].score must be within [0,1]")
        if not _is_nonempty_str(e.get("justification")):
            _log("error", "VALIDATION_ERROR")
            return _err("VALIDATION_ERROR", f"criteriaEvaluations[{i}].justification must be a non-empty string")

    # validate possible outcomes
    for i, p in enumerate(possibleOutcomes):
        if not isinstance(p, dict):
            _log("error", "VALIDATION_ERROR")
            return _err("VALIDATION_ERROR", f"possibleOutcomes[{i}] must be an object")
        if "id" in p and p["id"] is not None and not isinstance(p["id"], str):
            _log("error", "VALIDATION_ERROR")
            return _err("VALIDATION_ERROR", f"possibleOutcomes[{i}].id must be a string when provided")
        if not _is_nonempty_str(p.get("description")) or not _is_nonempty_str(p.get("optionId")):
            _log("error", "VALIDATION_ERROR")
            return _err("VALIDATION_ERROR", f"possibleOutcomes[{i}].description and optionId are required and non-empty")
        if not _in01(p.get("probability")):
            _log("error", "VALIDATION_ERROR")
            return _err("VALIDATION_ERROR", f"possibleOutcomes[{i}].probability must be within [0,1]")
        if not _finite_num(p.get("value")):
            _log("error", "VALIDATION_ERROR")
            return _err("VALIDATION_ERROR", f"possibleOutcomes[{i}].value must be a finite number")
        if not _in01(p.get("confidenceInEstimate")):
            _log("error", "VALIDATION_ERROR")
            return _err("VALIDATION_ERROR", f"possibleOutcomes[{i}].confidenceInEstimate must be within [0,1]")

    # validate information gaps
    for i, g in enumerate(informationGaps):
        if not isinstance(g, dict):
            _log("error", "VALIDATION_ERROR")
            return _err("VALIDATION_ERROR", f"informationGaps[{i}] must be an object")
        if not _is_nonempty_str(g.get("description")):
            _log("error", "VALIDATION_ERROR")
            return _err("VALIDATION_ERROR", f"informationGaps[{i}].description must be non-empty")
        if not _in01(g.get("impact")):
            _log("error", "VALIDATION_ERROR")
            return _err("VALIDATION_ERROR", f"informationGaps[{i}].impact must be within [0,1]")
        if not _is_nonempty_str(g.get("researchMethod")):
            _log("error", "VALIDATION_ERROR")
            return _err("VALIDATION_ERROR", f"informationGaps[{i}].researchMethod must be non-empty")

    # --- Load datastore ---
    decisions = _load("decisions.json")
    opts = _load("decision_options.json")
    crits = _load("decision_criteria.json")
    evals = _load("criteria_evaluations.json")
    risks = _load("decision_risk_items.json")

    if not isinstance(decisions, list): decisions = []
    if not isinstance(opts, list): opts = []
    if not isinstance(crits, list): crits = []
    if not isinstance(evals, list): evals = []
    if not isinstance(risks, list): risks = []

    # find decision by decision_id
    drow = None
    for r in decisions:
        if isinstance(r, dict) and r.get("decision_id") == decisionId:
            drow = r
            break

    now = _now()
    created = False
    if drow is None:
        # unique(decision_id)
        for r in decisions:
            if isinstance(r, dict) and r.get("decision_id") == decisionId:
                _log("error", "CONFLICT")
                return _err("CONFLICT", "decisionId already exists")
        drow = {
            "id": _gen_id("dec"),
            "decision_id": decisionId,
            "decision_statement": decisionStatement.strip(),
            "analysis_type": analysisType,
            "risk_tolerance": riskTolerance,
            "time_horizon": timeHorizon.strip(),
            "stage": stage,
            "iteration": iteration,
            "next_stage_needed": nextStageNeeded,
            "suggested_next_stage": suggestedNextStage if suggestedNextStage is not None else None,
            "status": "draft",
            "stakeholders": stakeholders,
            "constraints_list": constraints,
            "expected_values": None,
            "multi_criteria_scores": None,
            "sensitivity_insights": None,
            "recommendation": None,
            "created_at": now,
            "updated_at": now
        }
        decisions.append(drow)
        created = True
    else:
        # monotonic stage/iteration unless archived
        if drow.get("status") != "archived":
            prev_si = _stage_index(drow.get("stage"))
            if prev_si is None:
                prev_si = -1
            if si < prev_si:
                _log("error", "INVALID_TRANSITION")
                return _err("INVALID_TRANSITION", "stage cannot decrease for an active decision")
            if iteration < int(drow.get("iteration", 0) or 0):
                _log("error", "INVALID_TRANSITION")
                return _err("INVALID_TRANSITION", "iteration cannot decrease for an active decision")

        # update mutable fields
        drow["decision_statement"] = decisionStatement.strip()
        drow["analysis_type"] = analysisType
        drow["risk_tolerance"] = riskTolerance
        drow["time_horizon"] = timeHorizon.strip()
        drow["stage"] = stage
        drow["iteration"] = iteration
        drow["next_stage_needed"] = nextStageNeeded
        drow["suggested_next_stage"] = suggestedNextStage if suggestedNextStage is not None else None
        drow["stakeholders"] = stakeholders
        drow["constraints_list"] = constraints
        if expectedValues is not None:
            # validate values finite numbers
            for k, v in expectedValues.items():
                if not isinstance(k, str) or not _finite_num(v):
                    _log("error", "VALIDATION_ERROR")
                    return _err("VALIDATION_ERROR", "expectedValues must map string keys to finite numbers")
            drow["expected_values"] = expectedValues
        if multiCriteriaScores is not None:
            for k, v in multiCriteriaScores.items():
                if not isinstance(k, str) or not _finite_num(v):
                    _log("error", "VALIDATION_ERROR")
                    return _err("VALIDATION_ERROR", "multiCriteriaScores must map string keys to finite numbers")
            drow["multi_criteria_scores"] = multiCriteriaScores
        if sensitivityInsights is not None:
            drow["sensitivity_insights"] = sensitivityInsights
        if recommendation is not None:
            drow["recommendation"] = recommendation
        drow["updated_at"] = now

    decision_pk = drow["id"]

    # --- Upsert options keyed by (decision_id, option_key) ---
    existing_opts = [o for o in opts if isinstance(o, dict) and o.get("decision_id") == decision_pk]
    by_key = {o.get("option_key"): o for o in existing_opts if o.get("option_key") is not None}

    # assign stable keys for options without client id: try match by (name, description) existing; else assign opt_<n>
    used_keys = set(k for k in by_key.keys() if isinstance(k, str))
    def _next_opt_key():
        n = 1
        while True:
            k = f"opt_{n}"
            if k not in used_keys:
                used_keys.add(k)
                return k
            n += 1

    request_opt_keys = []
    for o in options:
        k = o.get("id")
        if k is None or (isinstance(k, str) and k.strip() == ""):
            # stable match by name+description in existing rows
            match = None
            for ex in existing_opts:
                if ex.get("name") == o.get("name") and ex.get("description") == o.get("description"):
                    match = ex
                    break
            if match is not None:
                k = match.get("option_key")
            else:
                k = _next_opt_key()
        if not isinstance(k, str) or k.strip() == "":
            _log("error", "VALIDATION_ERROR")
            return _err("VALIDATION_ERROR", "Option id resolution failed")
        request_opt_keys.append(k)

        # enforce unique(decision_id, option_key) in request
        if request_opt_keys.count(k) > 1:
            _log("error", "VALIDATION_ERROR")
            return _err("VALIDATION_ERROR", f"Duplicate option key within decision: {k}")

        if k in by_key:
            row = by_key[k]
            row["name"] = o["name"]
            row["description"] = o["description"]
            row["updated_at"] = now
            if row.get("status") not in ["active", "deprecated"]:
                row["status"] = "active"
        else:
            # ensure no conflicting existing with same key already (should be by_key)
            newr = {
                "id": _gen_id("opt"),
                "decision_id": decision_pk,
                "option_key": k,
                "name": o["name"],
                "description": o["description"],
                "status": "active",
                "created_at": now,
                "updated_at": now
            }
            opts.append(newr)
            by_key[k] = newr
            existing_opts.append(newr)

    # --- Upsert criteria keyed by (decision_id, criterion_key) ---
    existing_crits = [c for c in crits if isinstance(c, dict) and c.get("decision_id") == decision_pk]
    by_ckey = {c.get("criterion_key"): c for c in existing_crits if c.get("criterion_key") is not None}
    used_ckeys = set(k for k in by_ckey.keys() if isinstance(k, str))

    def _next_crit_key():
        n = 1
        while True:
            k = f"crit_{n}"
            if k not in used_ckeys:
                used_ckeys.add(k)
                return k
            n += 1

    request_crit_keys = []
    for c in criteria:
        k = c.get("id")
        if k is None or (isinstance(k, str) and k.strip() == ""):
            match = None
            for ex in existing_crits:
                if ex.get("name") == c.get("name") and ex.get("description") == c.get("description"):
                    match = ex
                    break
            if match is not None:
                k = match.get("criterion_key")
            else:
                k = _next_crit_key()
        if not isinstance(k, str) or k.strip() == "":
            _log("error", "VALIDATION_ERROR")
            return _err("VALIDATION_ERROR", "Criterion id resolution failed")
        request_crit_keys.append(k)
        if request_crit_keys.count(k) > 1:
            _log("error", "VALIDATION_ERROR")
            return _err("VALIDATION_ERROR", f"Duplicate criterion key within decision: {k}")

        if k in by_ckey:
            row = by_ckey[k]
            row["name"] = c["name"]
            row["description"] = c["description"]
            row["weight"] = float(c["weight"])
            row["evaluation_method"] = c["evaluationMethod"]
            row["updated_at"] = now
            if row.get("status") not in ["active", "deprecated"]:
                row["status"] = "active"
        else:
            newr = {
                "id": _gen_id("crit"),
                "decision_id": decision_pk,
                "criterion_key": k,
                "name": c["name"],
                "description": c["description"],
                "weight": float(c["weight"]),
                "evaluation_method": c["evaluationMethod"],
                "status": "active",
                "created_at": now,
                "updated_at": now
            }
            crits.append(newr)
            by_ckey[k] = newr
            existing_crits.append(newr)

    # enforce weights sum rule over active criteria
    active_criteria = [c for c in crits if isinstance(c, dict) and c.get("decision_id") == decision_pk and c.get("status") == "active"]
    wsum = 0.0
    for c in active_criteria:
        w = c.get("weight")
        if not _in01(w):
            _log("error", "VALIDATION_ERROR")
            return _err("VALIDATION_ERROR", "Stored criterion weight out of bounds", criterion_id=c.get("id"))
        wsum += float(w)
    if wsum > 1.0 + 1e-12:
        _log("error", "VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "Sum of active criterion weights must be <= 1.0", sumWeight=wsum)
    if analysisType == "multi-criteria" and si >= _stage_index("analysis"):
        if abs(wsum - 1.0) > 0.001:
            _log("error", "VALIDATION_ERROR")
            return _err("VALIDATION_ERROR", "For multi-criteria at stage >= 'analysis', sum of active criterion weights must be ~1.0 (±0.001)", sumWeight=wsum)

    # Build maps for evaluation resolution
    option_key_to_id = {o["option_key"]: o["id"] for o in opts if isinstance(o, dict) and o.get("decision_id") == decision_pk}
    crit_key_to_id = {c["criterion_key"]: c["id"] for c in crits if isinstance(c, dict) and c.get("decision_id") == decision_pk}

    # --- Upsert evaluations (unique active per decision, criterion_id, option_id) ---
    # resolve incoming keys first
    resolved_evals = []
    for e in criteriaEvaluations:
        ck = e["criterionId"]
        ok = e["optionId"]
        if ck not in crit_key_to_id:
            _log("error", "VALIDATION_ERROR")
            return _err("VALIDATION_ERROR", f"Unknown criterionId referenced in criteriaEvaluations: {ck}")
        if ok not in option_key_to_id:
            _log("error", "VALIDATION_ERROR")
            return _err("VALIDATION_ERROR", f"Unknown optionId referenced in criteriaEvaluations: {ok}")
        resolved_evals.append((crit_key_to_id[ck], option_key_to_id[ok], float(e["score"]), e["justification"].strip()))

    # upsert: if existing active row exists, update it; else create new active row
    # enforce uniqueness among incoming for same pair
    seen_pairs = set()
    for (cid, oid, score, justif) in resolved_evals:
        pair = (cid, oid)
        if pair in seen_pairs:
            _log("error", "VALIDATION_ERROR")
            return _err("VALIDATION_ERROR", "Duplicate criteria evaluation in request for same criterionId/optionId")
        seen_pairs.add(pair)

        existing_active = None
        for row in evals:
            if (isinstance(row, dict) and row.get("decision_id") == decision_pk and
                row.get("criterion_id") == cid and row.get("option_id") == oid and row.get("status") == "active"):
                existing_active = row
                break
        if existing_active is not None:
            existing_active["score"] = score
            existing_active["justification"] = justif
            existing_active["updated_at"] = now
        else:
            evals.append({
                "id": _gen_id("eval"),
                "decision_id": decision_pk,
                "criterion_id": cid,
                "option_id": oid,
                "score": score,
                "justification": justif,
                "status": "active",
                "created_at": now,
                "updated_at": now
            })

    # --- Upsert risk items: possible outcomes and information gaps ---
    # possible outcomes keyed by (decision_id, item_type, client_item_key) if provided; otherwise create new
    # information gaps have no client key; upsert by (decision_id, item_type, description) as a practical surrogate to avoid duplicates
    existing_risks = [r for r in risks if isinstance(r, dict) and r.get("decision_id") == decision_pk]

    def _find_risk(item_type, client_key, desc, option_id):
        for r in existing_risks:
            if r.get("item_type") != item_type:
                continue
            if client_key is not None:
                if r.get("client_item_key") == client_key:
                    return r
            else:
                # best-effort idempotency for gaps: match by description + type
                if item_type == "information_gap" and r.get("description") == desc:
                    return r
                # for outcomes without client id, match by description + option_id
                if item_type == "possible_outcome" and r.get("description") == desc and r.get("option_id") == option_id:
                    return r
        return None

    # possible outcomes
    for p in possibleOutcomes:
        ok = p["optionId"]
        if ok not in option_key_to_id:
            _log("error", "VALIDATION_ERROR")
            return _err("VALIDATION_ERROR", f"Unknown optionId referenced in possibleOutcomes: {ok}")
        option_id = option_key_to_id[ok]
        client_key = p.get("id")
        if client_key is not None and client_key.strip() == "":
            client_key = None
        # enforce uniqueness when client key present
        if client_key is not None:
            for r in existing_risks:
                if r.get("item_type") == "possible_outcome" and r.get("client_item_key") == client_key and r.get("decision_id") == decision_pk:
                    # ok, will update same row
                    break
            # also prevent duplicates within request
            # (decision_id, item_type, client_item_key)
        row = _find_risk("possible_outcome", client_key, p["description"].strip(), option_id)
        if row is None:
            row = {
                "id": _gen_id("risk"),
                "decision_id": decision_pk,
                "item_type": "possible_outcome",
                "client_item_key": client_key,
                "option_id": option_id,
                "description": p["description"].strip(),
                "probability": float(p["probability"]),
                "value": float(p["value"]),
                "confidence_in_estimate": float(p["confidenceInEstimate"]),
                "impact": None,
                "research_method": None,
                "status": "active",
                "created_at": now,
                "updated_at": now
            }
            risks.append(row)
            existing_risks.append(row)
        else:
            # validate existing type constraints implicitly by overwriting consistent fields
            row["option_id"] = option_id
            row["description"] = p["description"].strip()
            row["probability"] = float(p["probability"])
            row["value"] = float(p["value"])
            row["confidence_in_estimate"] = float(p["confidenceInEstimate"])
            row["impact"] = None
            row["research_method"] = None
            if row.get("status") not in ["active", "resolved", "deprecated"]:
                row["status"] = "active"
            row["updated_at"] = now

    # information gaps (active)
    for g in informationGaps:
        desc = g["description"].strip()
        row = _find_risk("information_gap", None, desc, None)
        if row is None:
            row = {
                "id": _gen_id("risk"),
                "decision_id": decision_pk,
                "item_type": "information_gap",
                "client_item_key": None,
                "option_id": None,
                "description": desc,
                "probability": None,
                "value": None,
                "confidence_in_estimate": None,
                "impact": float(g["impact"]),
                "research_method": g["researchMethod"].strip(),
                "status": "active",
                "created_at": now,
                "updated_at": now
            }
            risks.append(row)
            existing_risks.append(row)
        else:
            row["description"] = desc
            row["impact"] = float(g["impact"])
            row["research_method"] = g["researchMethod"].strip()
            # do not auto-resolve
            if row.get("status") not in ["active", "resolved", "deprecated"]:
                row["status"] = "active"
            row["updated_at"] = now

    # validate resolved gaps rule (even though this tool doesn't set resolved, caller may have existing rows)
    for r in existing_risks:
        if r.get("item_type") == "information_gap" and r.get("status") == "resolved":
            if not _is_nonempty_str(r.get("research_method")) or not _in01(r.get("impact")):
                _log("error", "VALIDATION_ERROR")
                return _err("VALIDATION_ERROR", "Resolved information gaps must have non-empty research_method and impact in [0,1]", risk_item_id=r.get("id"))

    # persist artifacts only if provided; enforce finalized implies recommendation at mutation time elsewhere
    # Save files
    _save("decisions.json", decisions)
    _save("decision_options.json", opts)
    _save("decision_criteria.json", crits)
    _save("criteria_evaluations.json", evals)
    _save("decision_risk_items.json", risks)

    # assemble full decision record response
    def _assemble(d):
        did = d["id"]
        o_rows = [o for o in opts if isinstance(o, dict) and o.get("decision_id") == did]
        c_rows = [c for c in crits if isinstance(c, dict) and c.get("decision_id") == did]
        e_rows = [e for e in evals if isinstance(e, dict) and e.get("decision_id") == did]
        r_rows = [r for r in risks if isinstance(r, dict) and r.get("decision_id") == did]

        options_out = []
        for o in sorted(o_rows, key=lambda x: (x.get("created_at") or "", x.get("id") or "")):
            options_out.append({
                "id": o.get("option_key"),
                "name": o.get("name"),
                "description": o.get("description"),
                "status": o.get("status")
            })

        criteria_out = []
        for c in sorted(c_rows, key=lambda x: (x.get("created_at") or "", x.get("id") or "")):
            criteria_out.append({
                "id": c.get("criterion_key"),
                "name": c.get("name"),
                "description": c.get("description"),
                "weight": c.get("weight"),
                "evaluationMethod": c.get("evaluation_method"),
                "status": c.get("status")
            })

        # map ids back to keys
        id_to_okey = {o.get("id"): o.get("option_key") for o in o_rows}
        id_to_ckey = {c.get("id"): c.get("criterion_key") for c in c_rows}

        evals_out = []
        for e in sorted(e_rows, key=lambda x: (x.get("created_at") or "", x.get("id") or "")):
            evals_out.append({
                "criterionId": id_to_ckey.get(e.get("criterion_id")),
                "optionId": id_to_okey.get(e.get("option_id")),
                "score": e.get("score"),
                "justification": e.get("justification"),
                "status": e.get("status")
            })

        possible_outcomes_out = []
        information_gaps_out = []
        for r in sorted(r_rows, key=lambda x: (x.get("created_at") or "", x.get("id") or "")):
            if r.get("item_type") == "possible_outcome":
                possible_outcomes_out.append({
                    "id": r.get("client_item_key"),
                    "description": r.get("description"),
                    "probability": r.get("probability"),
                    "optionId": id_to_okey.get(r.get("option_id")),
                    "value": r.get("value"),
                    "confidenceInEstimate": r.get("confidence_in_estimate"),
                    "status": r.get("status")
                })
            elif r.get("item_type") == "information_gap":
                information_gaps_out.append({
                    "description": r.get("description"),
                    "impact": r.get("impact"),
                    "researchMethod": r.get("research_method"),
                    "status": r.get("status")
                })

        return {
            "id": d.get("decision_id"),
            "decisionId": d.get("decision_id"),
            "decisionStatement": d.get("decision_statement"),
            "analysisType": d.get("analysis_type"),
            "riskTolerance": d.get("risk_tolerance"),
            "timeHorizon": d.get("time_horizon"),
            "stage": d.get("stage"),
            "iteration": d.get("iteration"),
            "nextStageNeeded": d.get("next_stage_needed"),
            "suggestedNextStage": d.get("suggested_next_stage"),
            "status": d.get("status"),
            "stakeholders": d.get("stakeholders"),
            "constraints": d.get("constraints_list"),
            "options": options_out,
            "criteria": criteria_out,
            "criteriaEvaluations": evals_out,
            "possibleOutcomes": possible_outcomes_out,
            "informationGaps": information_gaps_out,
            "expectedValues": d.get("expected_values"),
            "multiCriteriaScores": d.get("multi_criteria_scores"),
            "sensitivityInsights": d.get("sensitivity_insights"),
            "recommendation": d.get("recommendation"),
            "createdAt": d.get("created_at"),
            "updatedAt": d.get("updated_at")
        }

    body = _assemble(drow)
    _log("ok")
    return {"decision": body, "created": created}

def listDecisions(authToken, pageSize=None, pageToken=None, status=None, stage=None, analysisType=None, riskTolerance=None, decisionStatementContains=None, updatedAfter=None, updatedBefore=None, **_extra):
    import json, os, datetime, time, uuid

    _t0 = time.time()
    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0423000" if __import__("os").path.isdir("./environment_mix/0423000") else "/app/database")

    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []

    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)

    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    def _now():
        return datetime.datetime.now(datetime.timezone.utc).isoformat()

    def _gen_id(prefix):
        return f"{prefix}_{uuid.uuid4().hex}"

    def _parse_iso(s):
        if s is None:
            return None
        if not isinstance(s, str) or s.strip() == "":
            return "BAD"
        ss = s.strip()
        try:
            if ss.endswith("Z"):
                ss = ss[:-1] + "+00:00"
            return datetime.datetime.fromisoformat(ss)
        except Exception:
            return "BAD"

    def _log(status_s, error_code=None, credential=None):
        logs = _load("request_logs.json")
        if not isinstance(logs, list):
            logs = []
        logs.append({
            "id": _gen_id("req"),
            "endpoint": "listDecisions",
            "credential": credential,
            "status": status_s,
            "error_code": error_code,
            "latency_ms": int((time.time() - _t0) * 1000),
            "timestamp": _now()
        })
        _save("request_logs.json", logs)

    # authenticate: accept any token that matches a stored row if present; otherwise accept ambient
    tokens = _load("auth_tokens.json")
    cred = None
    if isinstance(tokens, list):
        for t in tokens:
            if isinstance(t, dict) and (t.get("token") == authToken or t.get("id") == authToken) and t.get("status", "active") == "active":
                cred = t.get("token") or t.get("id")
                break
    # if authToken provided but no store, accept (offline ambient)
    if not isinstance(authToken, str) or authToken.strip() == "":
        _log("error", "UNAUTHORIZED")
        return _err("UNAUTHORIZED", "authToken must be a non-empty string")

    # validate pagination
    if pageSize is None:
        pageSize = 50
    if not isinstance(pageSize, int) or pageSize < 1 or pageSize > 200:
        _log("error", "VALIDATION_ERROR", cred)
        return _err("VALIDATION_ERROR", "pageSize must be an integer between 1 and 200")
    if pageToken is not None and (not isinstance(pageToken, str)):
        _log("error", "VALIDATION_ERROR", cred)
        return _err("VALIDATION_ERROR", "pageToken must be a string")

    # validate filters
    if status is not None and status not in ["draft", "in_progress", "finalized", "archived"]:
        _log("error", "VALIDATION_ERROR", cred)
        return _err("VALIDATION_ERROR", "Invalid status filter")
    # stage enum in this tool uses problem_definition (underscore)
    if stage is not None and stage not in ["problem_definition", "options", "criteria", "evaluation", "analysis", "recommendation"]:
        _log("error", "VALIDATION_ERROR", cred)
        return _err("VALIDATION_ERROR", "Invalid stage filter")
    stage_map = {"problem_definition": "problem-definition"}
    stage_norm = stage_map.get(stage, stage) if stage is not None else None

    if analysisType is not None and analysisType not in ["expected-utility", "multi-criteria"]:
        _log("error", "VALIDATION_ERROR", cred)
        return _err("VALIDATION_ERROR", "Invalid analysisType filter")
    if riskTolerance is not None and riskTolerance not in ["risk-averse", "risk-neutral", "risk-seeking"]:
        _log("error", "VALIDATION_ERROR", cred)
        return _err("VALIDATION_ERROR", "Invalid riskTolerance filter")
    if decisionStatementContains is not None and not isinstance(decisionStatementContains, str):
        _log("error", "VALIDATION_ERROR", cred)
        return _err("VALIDATION_ERROR", "decisionStatementContains must be a string")

    ua = _parse_iso(updatedAfter)
    ub = _parse_iso(updatedBefore)
    if ua == "BAD" or ub == "BAD":
        _log("error", "VALIDATION_ERROR", cred)
        return _err("VALIDATION_ERROR", "updatedAfter/updatedBefore must be ISO-8601 timestamps")

    decisions = _load("decisions.json")
    if not isinstance(decisions, list):
        decisions = []

    # filter
    rows = []
    needle = decisionStatementContains.lower() if isinstance(decisionStatementContains, str) else None
    for d in decisions:
        if not isinstance(d, dict):
            continue
        if status is not None and d.get("status") != status:
            continue
        if stage_norm is not None and d.get("stage") != stage_norm:
            continue
        if analysisType is not None and d.get("analysis_type") != analysisType:
            continue
        if riskTolerance is not None and d.get("risk_tolerance") != riskTolerance:
            continue
        if needle is not None:
            ds = d.get("decision_statement") or ""
            if not isinstance(ds, str) or needle not in ds.lower():
                continue
        if ua is not None:
            du = _parse_iso(d.get("updated_at"))
            if isinstance(du, datetime.datetime):
                if du < ua:
                    continue
        if ub is not None:
            du = _parse_iso(d.get("updated_at"))
            if isinstance(du, datetime.datetime):
                if du > ub:
                    continue
        rows.append(d)

    # sort by updated_at desc
    def _sort_key(d):
        s = d.get("updated_at") or ""
        return s
    rows.sort(key=_sort_key, reverse=True)

    # cursor paging: pageToken = updated_at|id|offset
    start = 0
    if pageToken:
        parts = pageToken.split("|")
        if len(parts) == 3:
            tok_updated, tok_id, tok_offset = parts
            try:
                tok_offset = int(tok_offset)
            except Exception:
                tok_offset = None
            if tok_offset is None:
                _log("error", "VALIDATION_ERROR", cred)
                return _err("VALIDATION_ERROR", "Invalid pageToken")
            # find first index after the referenced item, then add offset
            idx = None
            for i, d in enumerate(rows):
                if (d.get("updated_at") or "") == tok_updated and (d.get("id") or "") == tok_id:
                    idx = i + 1
                    break
            if idx is None:
                # token no longer valid against current set -> treat as start
                start = 0
            else:
                start = idx + tok_offset
        else:
            _log("error", "VALIDATION_ERROR", cred)
            return _err("VALIDATION_ERROR", "Invalid pageToken")

    page = rows[start:start + pageSize]
    has_more = start + pageSize < len(rows)
    next_cursor = None
    if has_more and len(page) > 0:
        last = page[-1]
        next_cursor = f"{last.get('updated_at') or ''}|{last.get('id') or ''}|0"

    # minimal decision summary envelope
    out = []
    for d in page:
        out.append({
            "decisionId": d.get("decision_id"),
            "decisionStatement": d.get("decision_statement"),
            "analysisType": d.get("analysis_type"),
            "riskTolerance": d.get("risk_tolerance"),
            "timeHorizon": d.get("time_horizon"),
            "stage": d.get("stage"),
            "iteration": d.get("iteration"),
            "status": d.get("status"),
            "updatedAt": d.get("updated_at"),
            "createdAt": d.get("created_at")
        })

    _log("ok", credential=cred)
    return {"decisions": out, "pageSize": pageSize, "total": len(rows), "hasMore": has_more, "nextPageToken": next_cursor}

