    evals = _load("criteria_evaluations.json")
    risks = _load("decision_risk_items.json")
    if not isinstance(decisions, list): decisions = []
    if not isinstance(opts, list): opts = []
    if not isinstance(crits, list): crits = []
    if not isinstance(evals, list): evals = []
    if not isinstance(risks, list): risks = []

    drow = None
    for d in decisions:
        if isinstance(d, dict) and d.get("decision_id") == decisionId:
            drow = d
            break
    if drow is None:
        _log("error", "NOT_FOUND", cred)
        return _err("NOT_FOUND", "Decision not found")

    current = drow.get("status")
    transitions = {
        "draft": ["in_progress", "archived"],
        "in_progress": ["finalized", "archived"],
        "finalized": ["archived"],
        "archived": []
    }
    if current not in transitions:
        _log("error", "INVALID_TRANSITION", cred)
        return _err("INVALID_TRANSITION", "Current decision status is invalid")
    if status == current:
        # idempotent
        _log("ok", credential=cred)
        return {"decisionId": decisionId, "status": current, "updatedAt": drow.get("updated_at")}

    if status not in transitions[current]:
        _log("error", "INVALID_TRANSITION", cred)
        return _err("INVALID_TRANSITION", f"Illegal transition {current} -> {status}")

    did = drow["id"]
    now = _now()

    # When finalizing, enforce rules and compute artifacts
    if status == "finalized":
        if not _is_nonempty_str(drow.get("recommendation")):
            _log("error", "VALIDATION_ERROR", cred)
            return _err("VALIDATION_ERROR", "Finalizing requires a non-empty recommendation in the decision record (set via decisionFramework)")

        analysis_type = drow.get("analysis_type")
        stg = drow.get("stage")
        si = _stage_index(stg) if stg is not None else None
        if si is None:
            _log("error", "VALIDATION_ERROR", cred)
            return _err("VALIDATION_ERROR", "Decision stage is invalid")
        if si < _stage_index("analysis"):
            _log("error", "VALIDATION_ERROR", cred)
            return _err("VALIDATION_ERROR", "Decision must be at stage >= 'analysis' to finalize")

        active_opts = [o for o in opts if isinstance(o, dict) and o.get("decision_id") == did and o.get("status") == "active"]
        if len(active_opts) == 0:
            _log("error", "VALIDATION_ERROR", cred)
            return _err("VALIDATION_ERROR", "Cannot finalize without at least one active option")

        active_crits = [c for c in crits if isinstance(c, dict) and c.get("decision_id") == did and c.get("status") == "active"]
        wsum = sum(float(c.get("weight", 0.0) or 0.0) for c in active_crits)
        if wsum > 1.0 + 1e-12:
            _log("error", "VALIDATION_ERROR", cred)
            return _err("VALIDATION_ERROR", "Sum of active criterion weights must be <= 1.0", sumWeight=wsum)
        if analysis_type == "multi-criteria":
            if abs(wsum - 1.0) > 0.001:
                _log("error", "VALIDATION_ERROR", cred)
                return _err("VALIDATION_ERROR", "For multi-criteria at stage >= 'analysis', sum of active criterion weights must be ~1.0 (±0.001)", sumWeight=wsum)

        # compute artifacts
        if analysis_type == "expected-utility":
            # each active option must have at least one active outcome at stage>=analysis
            outcomes = [r for r in risks if isinstance(r, dict) and r.get("decision_id") == did and r.get("item_type") == "possible_outcome" and r.get("status") == "active"]
            by_opt = {}
            for r in outcomes:
                oid = r.get("option_id")
                if oid is None:
                    continue
                by_opt.setdefault(oid, []).append(r)
            for o in active_opts:
                if o.get("id") not in by_opt or len(by_opt[o.get("id")]) == 0:
                    _log("error", "VALIDATION_ERROR", cred)
                    return _err("VALIDATION_ERROR", "Each active option must have at least one active possible outcome to finalize expected-utility decisions", optionId=o.get("option_key"))
            expected_values = {}
            for o in active_opts:
                oid = o.get("id")
                ev = 0.0
                for r in by_opt.get(oid, []):
                    p = r.get("probability")
                    v = r.get("value")
                    if not _in01(p) or not isinstance(v, (int, float)) or not math.isfinite(float(v)):
                        _log("error", "VALIDATION_ERROR", cred)
                        return _err("VALIDATION_ERROR", "Outcome probability/value invalid for finalization", riskItemId=r.get("id"))
                    ev += float(p) * float(v)
                expected_values[o.get("option_key")] = ev
            drow["expected_values"] = expected_values
            if drow.get("multi_criteria_scores") is None:
                drow["multi_criteria_scores"] = None

        elif analysis_type == "multi-criteria":
            # each active option must have active eval for each active criterion
            active_evals = [e for e in evals if isinstance(e, dict) and e.get("decision_id") == did and e.get("status") == "active"]
            eval_set = set((e.get("criterion_id"), e.get("option_id")) for e in active_evals)
            for c in active_crits:
                for o in active_opts:
                    if (c.get("id"), o.get("id")) not in eval_set:
                        _log("error", "VALIDATION_ERROR", cred)
                        return _err("VALIDATION_ERROR", "Each active option must have an active evaluation for each active criterion to finalize multi-criteria decisions",
                                    criterionId=c.get("criterion_key"), optionId=o.get("option_key"))
            # score = sum(weight * score)
            weights = {c.get("id"): float(c.get("weight")) for c in active_crits}
            mcs = {}
            for o in active_opts:
                total = 0.0
                for c in active_crits:
                    # find eval row
                    s = None
                    for e in active_evals:
                        if e.get("criterion_id") == c.get("id") and e.get("option_id") == o.get("id"):
                            s = e.get("score")
                            break
                    if not _in01(s):
                        _log("error", "VALIDATION_ERROR", cred)
                        return _err("VALIDATION_ERROR", "Evaluation score out of bounds for finalization", criterionId=c.get("criterion_key"), optionId=o.get("option_key"))
                    total += weights[c.get("id")] * float(s)
                mcs[o.get("option_key")] = total
            drow["multi_criteria_scores"] = mcs
            if drow.get("expected_values") is None:
                drow["expected_values"] = None
        else:
            # For other analysis types, require recommendation but do not compute artifacts
            pass

        if not _is_nonempty_str(drow.get("recommendation")):
            _log("error", "VALIDATION_ERROR", cred)
            return _err("VALIDATION_ERROR", "Finalized decisions must have a non-empty recommendation")

    # apply transition
    drow["status"] = status
    drow["updated_at"] = now

    _save("decisions.json", decisions)
    _log("ok", credential=cred)
    return {"decisionId": decisionId, "status": drow["status"], "updatedAt": drow["updated_at"]}

def listDecisionOptions(authToken, decisionId, pageSize=None, pageToken=None, status=None, **_extra):
    import json, os, datetime, time, base64, hashlib

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0423000" if __import__("os").path.isdir("./environment_mix/0423000") else "/app/database")

    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []

    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)

    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    def _now():
        return datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"

    def _is_str(x):
        return isinstance(x, str)

    def _parse_cursor(tok):
        if tok is None:
            return None
        if not isinstance(tok, str) or not tok:
            return None
        try:
            pad = "=" * (-len(tok) % 4)
            raw = base64.urlsafe_b64decode((tok + pad).encode("utf-8")).decode("utf-8")
            obj = json.loads(raw)
            return obj if isinstance(obj, dict) else None
        except Exception:
            return None

    def _make_cursor(obj):
        raw = json.dumps(obj, separators=(",", ":"), ensure_ascii=False).encode("utf-8")
        return base64.urlsafe_b64encode(raw).decode("utf-8").rstrip("=")

    def _hash_token(t):
        return hashlib.sha256(t.encode("utf-8")).hexdigest()

    def _resolve_auth(token):
        # Prefer real auth store if present; otherwise allow any non-empty token as authenticated.
        tokens = _load("auth_tokens.json")
        if isinstance(tokens, list) and tokens:
            for row in tokens:
                if not isinstance(row, dict):
                    continue
                if row.get("token") == token or row.get("id") == token:
                    if row.get("status") in (None, "active"):
                        return {"principal": row.get("principal") or row.get("account_id") or row.get("user_id") or row.get("id"), "token_id": row.get("id") or token, "scopes": row.get("scopes") or []}
            return None
        # Fallback: accept any non-empty token, but still track per-token usage.
        return {"principal": "token:" + _hash_token(token)[:16], "token_id": "token:" + _hash_token(token), "scopes": ["*"]}

    def _usage_load():
        return _load("request_logs.json")

    def _usage_save(rows):
        _save("request_logs.json", rows)

    def _enforce_limits(principal, endpoint):
        # Simple global per-principal rolling rate limit and daily quota, backed by request_logs.json
        rows = _usage_load()
        now = datetime.datetime.utcnow()
        window_s = 60
        rate_limit = 120  # per minute
        daily_quota = 5000

        recent = 0
        daily = 0
        for r in rows if isinstance(rows, list) else []:
            if not isinstance(r, dict):
                continue
            if r.get("principal") != principal:
                continue
            ts = r.get("ts")
            try:
                dt = datetime.datetime.fromisoformat(ts.replace("Z", "+00:00")).replace(tzinfo=None)
            except Exception:
                continue
            if (now - dt).total_seconds() <= window_s:
                recent += 1
            if dt.date() == now.date():
                daily += 1

        if recent >= rate_limit:
            return ("RATE_LIMIT", f"Rate limit exceeded for {endpoint}. Try again later.", rows)
        if daily >= daily_quota:
            return ("QUOTA_EXCEEDED", f"Daily quota exceeded for {endpoint}.", rows)
        return (None, None, rows)

    def _log_call(rows, principal, token_id, endpoint, status, latency_ms, meta=None):
        if not isinstance(rows, list):
            rows = []
        rec = {
            "id": "req_" + hashlib.sha1((principal + endpoint + _now() + str(time.time())).encode("utf-8")).hexdigest(),
            "ts": _now(),
            "principal": principal,
            "token_id": token_id,
            "endpoint": endpoint,
            "status": status,
            "latency_ms": int(latency_ms),
        }
        if isinstance(meta, dict) and meta:
            rec["meta"] = meta
        rows.append(rec)
        _usage_save(rows)

    start = time.time()

    # Validate inputs
    if not _is_str(authToken) or not authToken.strip():
        return _err("UNAUTHORIZED", "Missing or invalid authToken.")
    if not _is_str(decisionId) or not decisionId.strip():
        return _err("VALIDATION_ERROR", "decisionId must be a non-empty string.")
    if pageSize is None:
        pageSize = 50
    if not isinstance(pageSize, int) or pageSize < 1 or pageSize > 500:
        return _err("VALIDATION_ERROR", "pageSize must be an integer between 1 and 500.")
    if pageToken is not None and not _is_str(pageToken):
        return _err("VALIDATION_ERROR", "pageToken must be a string.")
    if status is not None:
        if not _is_str(status) or status not in ("active", "deprecated"):
            return _err("VALIDATION_ERROR", "status must be one of: active, deprecated.")

    # Auth + limits
    auth = _resolve_auth(authToken.strip())
    if not auth:
        return _err("UNAUTHORIZED", "Invalid authToken.")
    principal = auth["principal"]
    token_id = auth["token_id"]
    endpoint = "listDecisionOptions"

    code, msg, log_rows = _enforce_limits(principal, endpoint)
    if code:
        _log_call(log_rows, principal, token_id, endpoint, code, (time.time() - start) * 1000)
        return _err(code, msg)

    # Resolve decision by client decision_id
    decisions = _load("decisions.json")
    decision_row = None
    if isinstance(decisions, list):
        for d in decisions:
            if isinstance(d, dict) and d.get("decision_id") == decisionId:
                decision_row = d
                break
    if not decision_row:
        _log_call(log_rows, principal, token_id, endpoint, "NOT_FOUND", (time.time() - start) * 1000, {"decisionId": decisionId})
        return _err("NOT_FOUND", "Decision not found.")

    decision_pk = decision_row.get("id")
    options = _load("decision_options.json")
    if not isinstance(options, list):
        options = []

    # Cursor handling
    cursor = _parse_cursor(pageToken) if pageToken else None
    start_after = None
    if cursor:
        if cursor.get("decisionId") != decisionId:
            _log_call(log_rows, principal, token_id, endpoint, "VALIDATION_ERROR", (time.time() - start) * 1000)
            return _err("VALIDATION_ERROR", "pageToken does not match this decisionId.")
        if status is not None and cursor.get("status") != status:
            _log_call(log_rows, principal, token_id, endpoint, "VALIDATION_ERROR", (time.time() - start) * 1000)
            return _err("VALIDATION_ERROR", "pageToken does not match this status filter.")
        start_after = cursor.get("after")  # option_key

    # Filter + sort
    rows = []
    for o in options:
        if not isinstance(o, dict):
            continue
        if o.get("decision_id") != decision_pk:
            continue
        if status is not None and o.get("status") != status:
            continue
        rows.append(o)

    rows.sort(key=lambda r: (str(r.get("option_key") or ""), str(r.get("id") or "")))

    total = len(rows)
    if start_after is not None:
        # Find first row with option_key > start_after (or if equal, continue after)
        filtered = []
        passed = False
        for r in rows:
            ok = str(r.get("option_key") or "")
            if passed:
                filtered.append(r)
            else:
                if ok > str(start_after):
                    passed = True
                    filtered.append(r)
        rows_pageable = filtered
    else:
        rows_pageable = rows

    page = rows_pageable[:pageSize]
    has_more = len(rows_pageable) > pageSize
    next_token = None
    if has_more and page:
        last = page[-1]
        next_token = _make_cursor({"decisionId": decisionId, "status": status, "after": last.get("option_key")})

    resp = {
        "options": [
            {
                "id": r.get("option_key"),
                "name": r.get("name"),
                "description": r.get("description"),
                "status": r.get("status"),
                "createdAt": r.get("created_at"),
                "updatedAt": r.get("updated_at"),
            }
            for r in page
        ],
        "page": {
            "pageSize": pageSize,
            "total": total,
            "hasMore": bool(has_more),
            "nextPageToken": next_token,
        },
    }

    _log_call(log_rows, principal, token_id, endpoint, "OK", (time.time() - start) * 1000, {"decisionId": decisionId, "returned": len(page)})
    return resp

def whoAmI(authToken, **_extra):
    import json, os, datetime, time, hashlib

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0423000" if __import__("os").path.isdir("./environment_mix/0423000") else "/app/database")

    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []

    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)

    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    def _now():
        return datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"

    def _is_str(x):
        return isinstance(x, str)

    def _resolve_auth_strict(token):
        # whoAmI must refuse if token invalid. Prefer auth_tokens.json if present; otherwise treat "invalid"
        # as missing unless a token registry exists. To remain usable offline, accept any non-empty token ONLY
        # if there is no auth store.
        tokens = _load("auth_tokens.json")
        if isinstance(tokens, list) and tokens:
            for row in tokens:
                if not isinstance(row, dict):
                    continue
                if row.get("token") == token or row.get("id") == token:
                    if row.get("status") in (None, "active"):
                        return {"principal": row.get("principal") or row.get("account_id") or row.get("user_id") or row.get("id"), "token_id": row.get("id") or token, "scopes": row.get("scopes") or []}
            return None
        # No auth store: accept any non-empty token as authenticated
        h = hashlib.sha256(token.encode("utf-8")).hexdigest()
        return {"principal": "token:" + h[:16], "token_id": "token:" + h, "scopes": ["*"]}

    def _usage_load():
        return _load("request_logs.json")

    def _usage_save(rows):
        _save("request_logs.json", rows)

    def _log_call(rows, principal, token_id, endpoint, status_code, latency_ms, meta=None):
        if not isinstance(rows, list):
            rows = []
        rec = {
            "id": "req_" + hashlib.sha1((principal + endpoint + _now() + str(time.time())).encode("utf-8")).hexdigest(),
            "ts": _now(),
            "principal": principal,
            "token_id": token_id,
            "endpoint": endpoint,
            "status": status_code,
            "latency_ms": int(latency_ms),
        }
        if isinstance(meta, dict) and meta:
            rec["meta"] = meta
        rows.append(rec)
        _usage_save(rows)

    def _compute_consumption(rows, principal):
        now = datetime.datetime.utcnow()
        window_s = 60
        rate_limit = 120
        daily_quota = 5000

        recent = 0
        daily = 0
        for r in rows if isinstance(rows, list) else []:
            if not isinstance(r, dict):
                continue
            if r.get("principal") != principal:
                continue
            ts = r.get("ts")
            try:
                dt = datetime.datetime.fromisoformat(ts.replace("Z", "+00:00")).replace(tzinfo=None)
            except Exception:
                continue
            if (now - dt).total_seconds() <= window_s:
                recent += 1
            if dt.date() == now.date():
                daily += 1

        return {
            "rateLimit": {"windowSeconds": window_s, "limit": rate_limit, "used": recent, "remaining": max(0, rate_limit - recent)},
            "quota": {"period": "day", "limit": daily_quota, "used": daily, "remaining": max(0, daily_quota - daily)},
        }

    start = time.time()
    endpoint = "whoAmI"

    if not _is_str(authToken) or not authToken.strip():
        return _err("UNAUTHORIZED", "Missing authToken.")

    auth = _resolve_auth_strict(authToken.strip())
    if not auth:
        # No logging possible with unknown principal; log as anonymous hashed token bucket
        rows = _usage_load()
        anon_principal = "anon:" + hashlib.sha256(authToken.strip().encode("utf-8")).hexdigest()[:16]
        _log_call(rows, anon_principal, None, endpoint, "UNAUTHORIZED", (time.time() - start) * 1000)
        return _err("UNAUTHORIZED", "Invalid authToken.")

    principal = auth["principal"]
    token_id = auth["token_id"]
    scopes = auth.get("scopes") or []

    rows = _usage_load()
    consumption = _compute_consumption(rows, principal)

    # Enforce limits for this call too (observable dynamics); if exceeded, refuse
    if consumption["rateLimit"]["used"] >= consumption["rateLimit"]["limit"]:
        _log_call(rows, principal, token_id, endpoint, "RATE_LIMIT", (time.time() - start) * 1000)
        return _err("RATE_LIMIT", "Rate limit exceeded for whoAmI. Try again later.", **consumption)
    if consumption["quota"]["used"] >= consumption["quota"]["limit"]:
        _log_call(rows, principal, token_id, endpoint, "QUOTA_EXCEEDED", (time.time() - start) * 1000)
        return _err("QUOTA_EXCEEDED", "Daily quota exceeded for whoAmI.", **consumption)

    body = {
        "principal": principal,
        "tokenId": token_id,
        "scopes": scopes,
        "consumption": consumption,
    }

    _log_call(rows, principal, token_id, endpoint, "OK", (time.time() - start) * 1000)
    return body
